class Resource extends Base {
 mount(){this.chapters??=[{title:'Begin with space.',body:'Clear a little room. The best ideas often arrive when you stop filling every corner.'},{title:'Follow the material.',body:'Paper, light, a turn in the path. Let the texture tell you what belongs here.'},{title:'Leave something open.',body:'A good ending gives someone else a place to begin. Make room for their version.'}];this.render(`<section class="journey"><nav aria-label="Story chapters">${this.chapters.map((c,i)=>`<button data-index="${i}" aria-current="${i===0?'step':'false'}"><small>0${i+1}</small><span>${escape(c.title)}</span></button>`).join('')}<div class="track"><i></i></div></nav><div class="scroller" tabindex="0" aria-label="Scroll through the story">${this.chapters.map((chapter,i)=>`<article data-step="${i}"><span class="label">A FIELD GUIDE / 0${i+1}</span><div class="sculpture sculpture-${i}" aria-hidden="true"><i></i><i></i><i></i></div><h2>${escape(chapter.title)}</h2><p>${escape(chapter.body)}</p><small>SCROLL TO CONTINUE ↓</small></article>`).join('')}</div></section>`,`.journey{display:grid;grid-template-columns:155px minmax(0,1fr);height:490px;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;background:var(--bg)}nav{padding:30px 18px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:12px}nav button{display:flex;flex-direction:column;align-items:flex-start;gap:8px;background:none;border:0;border-left:2px solid transparent;border-radius:0;padding:10px 0 10px 12px;text-align:left;color:var(--muted);font-size:11px}nav button small{font:10px ui-monospace,monospace}nav [aria-current=step]{border-left-color:var(--accent);color:var(--ink)}.track{height:2px;background:var(--line);margin-top:auto}.track i{display:block;height:2px;background:var(--accent);transform-origin:left;transform:scaleX(0)}.scroller{overflow-y:auto;scroll-snap-type:y proximity;overscroll-behavior:contain}article{min-height:100%;padding:40px 28px;scroll-snap-align:start;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;position:relative;overflow:hidden}article:nth-child(2){background:#b0906820}article:nth-child(3){background:#98ad8d15}article h2{font-size:clamp(27px,4vw,42px);line-height:1.12;letter-spacing:-1.7px;font-weight:450;position:relative;max-width:280px;margin:18px 0}article p{color:var(--muted);max-width:260px;font-size:13px;line-height:1.9;position:relative}article>small{color:var(--muted);font-size:8px;letter-spacing:1px;margin-top:25px}.sculpture{height:140px;width:210px;position:relative;align-self:center;margin:20px 0 4px}.sculpture i{position:absolute;width:100px;height:100px;border:1px solid #c6e6b044;background:linear-gradient(135deg,#a6bea666,#364b4922);left:35px;top:10px;transform:rotate(45deg);box-shadow:15px 20px 0 #0002}.sculpture i:nth-child(2){left:70px;top:25px;opacity:.65}.sculpture i:nth-child(3){left:100px;top:40px;opacity:.3}.sculpture-1 i{border-radius:50% 50% 0 0;background:linear-gradient(140deg,#cba77d88,#80604022)}.sculpture-2 i{border-radius:50%;background:linear-gradient(140deg,#cecfbb77,#73846a22)}@media(max-width:480px){.journey{grid-template-columns:78px minmax(0,1fr)}nav{padding:20px 10px}nav button{padding-left:7px;font-size:9px}nav button span{line-height:1.6}article{padding:28px 20px}.sculpture{width:160px;transform:scale(.8)}}`);this.listen(this.$('.scroller'),'scroll',()=>this.update());this.listen(this.$('nav'),'click',e=>{const button=e.target.closest('button');if(button)this.goTo(Number(button.dataset.index));});this.update();}
 update(){const box=this.$('.scroller');const index=clamp(Math.round(box.scrollTop/box.clientHeight),0,this.chapters.length-1);const progress=box.scrollTop/(box.scrollHeight-box.clientHeight||1);this.$$('.sculpture').forEach((node,i)=>{node.style.translate=`0 ${this.reduced?0:clamp((box.scrollTop/box.clientHeight-i)*28*this.number('speed',1,.2,2),-30,30)}px`;});this.$$('.track i').forEach(n=>n.style.transform=`scaleX(${progress})`);this.$$('nav button').forEach((b,i)=>b.setAttribute('aria-current',i===index?'step':'false'));if(index!==this.index){this.index=index;this.emit('chapter-change',{index,progress});}}
 goTo(index){this.$('.scroller').scrollTo({top:clamp(index,0,this.chapters.length-1)*this.$('.scroller').clientHeight,behavior:this.reduced?'auto':'smooth'});}
}
